#!/usr/bin/env python3
"""
Test a list of OpenAI-compatible models against:

    "Reply with exactly one word: OK"

Usage:
    python test_models.py models.json

Expected JSON formats:
    ["model-a", "model-b"]
or
    {"models": ["model-a", "model-b"]}
or
    [{"model": "model-a"}, {"name": "model-b"}]
"""

import json
import sys
import time
from socket import timeout as SocketTimeout
from urllib import error, request

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30


def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if isinstance(data, dict):
        if "models" in data:
            data = data["models"]
        elif "model" in data or "name" in data:
            data = [data]
        else:
            # Treat top-level dict as {model_name: ...}
            data = [{"model": k} for k in data.keys()]

    if not isinstance(data, list):
        raise ValueError("JSON must be a list of models or contain a 'models' list")

    models = []
    for item in data:
        if isinstance(item, str):
            models.append(item)
        elif isinstance(item, dict):
            name = item.get("model") or item.get("name") or item.get("id")
            if not name:
                raise ValueError(f"Could not determine model name from entry: {item!r}")
            models.append(str(name))
        else:
            raise ValueError(f"Unsupported model entry: {item!r}")

    return models


def join_text(content):
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for part in content:
            if isinstance(part, str):
                parts.append(part)
            elif isinstance(part, dict):
                if "text" in part:
                    parts.append(str(part["text"]))
                elif "content" in part:
                    parts.append(str(part["content"]))
        return "".join(parts)
    return str(content)


def extract_text_from_json(obj):
    if not isinstance(obj, dict):
        return str(obj)

    # Common response shapes
    if "choices" in obj and obj["choices"]:
        choice = obj["choices"][0]
        if isinstance(choice, dict):
            message = choice.get("message")
            if isinstance(message, dict) and "content" in message:
                return join_text(message.get("content"))
            if "text" in choice:
                return join_text(choice.get("text"))

    # Common error shapes
    if "error" in obj:
        err = obj["error"]
        if isinstance(err, dict):
            return str(err.get("message") or err.get("detail") or json.dumps(err))
        return str(err)

    if "detail" in obj:
        return join_text(obj["detail"])
    if "message" in obj:
        return join_text(obj["message"])

    return ""


def response_text_from_raw(raw_text):
    try:
        obj = json.loads(raw_text)
        text = extract_text_from_json(obj)
        return text if text else raw_text
    except json.JSONDecodeError:
        return raw_text


def should_retry_without_temperature(error_text):
    t = (error_text or "").lower()
    return "temperature" in t and (
        "support" in t
        or "unsupported" in t
        or "invalid" in t
        or "unrecognized" in t
        or "not allowed" in t
        or "extra" in t
    )


def normalize_preview(text):
    text = text.replace("\r", " ").replace("\n", " ").replace("\t", " ")
    text = " ".join(text.split())
    return text[:50]


def send_request(model, include_temperature):
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": PROMPT}],
        "max_tokens": 20,
    }
    if include_temperature:
        payload["temperature"] = 0.0

    body = json.dumps(payload).encode("utf-8")
    req = request.Request(
        API_URL,
        data=body,
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
        method="POST",
    )

    try:
        with request.urlopen(req, timeout=TIMEOUT_SECONDS) as resp:
            raw = resp.read().decode("utf-8", "replace")
        text = response_text_from_raw(raw)
        return True, text
    except error.HTTPError as exc:
        raw = exc.read().decode("utf-8", "replace") if hasattr(exc, "read") else str(exc)
        text = response_text_from_raw(raw)
        return False, text
    except (error.URLError, TimeoutError, SocketTimeout, OSError, ValueError) as exc:
        return False, str(exc)


def test_model(model):
    start = time.perf_counter()

    # First try with temperature=0.0. If the server/model rejects it,
    # retry once without temperature.
    ok, text = send_request(model, include_temperature=True)
    if not ok and should_retry_without_temperature(text):
        ok, text = send_request(model, include_temperature=False)

    latency = time.perf_counter() - start
    response_preview = normalize_preview(text)

    passed = ok and text.strip() == "OK"
    return {
        "model": model,
        "status": "PASS" if passed else "FAIL",
        "latency": latency,
        "response": response_preview,
        "working": passed,
    }


def print_table(results):
    if not results:
        headers = ["Model", "Status", "Latency", "Response"]
        print(f"{headers[0]:<5} | {headers[1]:<6} | {headers[2]:<7} | {headers[3]}")
        print("-" * 5 + "-+-" + "-" * 6 + "-+-" + "-" * 7 + "-+-" + "-" * 50)
        return

    model_w = max(len("Model"), max(len(r["model"]) for r in results))
    status_w = max(len("Status"), len("FAIL"))
    latency_w = len("Latency")
    response_w = max(len("Response"), min(50, max(len(r["response"]) for r in results)))

    header = (
        f"{'Model':<{model_w}} | "
        f"{'Status':<{status_w}} | "
        f"{'Latency':>{latency_w}} | "
        f"{'Response':<{response_w}}"
    )
    print(header)
    print(
        f"{'-' * model_w}-+-"
        f"{'-' * status_w}-+-"
        f"{'-' * latency_w}-+-"
        f"{'-' * response_w}"
    )

    for r in results:
        latency_str = f"{r['latency']:.3f}s"
        print(
            f"{r['model']:<{model_w}} | "
            f"{r['status']:<{status_w}} | "
            f"{latency_str:>{latency_w}} | "
            f"{r['response']:<{response_w}}"
        )


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <models.json>", file=sys.stderr)
        sys.exit(1)

    try:
        models = load_models(sys.argv[1])
    except Exception as e:
        print(f"Failed to load models: {e}", file=sys.stderr)
        sys.exit(1)

    results = [test_model(model) for model in models]

    print_table(results)

    total = len(results)
    working = sum(1 for r in results if r["working"])
    failed = total - working
    print(f"Total: {total} models | ✅ {working} working | ❌ {failed} failed")


if __name__ == "__main__":
    main()
